        "content": "/**\n * Validates JSON input from stdin.\n *\n * Reads all input from stdin, attempts to parse it as JSON,\n * and exits with code 0 on success or code 1 on failure.\n */\n\nconst input = await Bun.stdin.text();\n\nif (!input.trim()) {\n  console.error(\"Error: No input provided\");\n  process.exit(1);\n}\n\ntry {\n  const parsed = JSON.parse(input);\n  console.log(\"Valid JSON\");\n  console.log(JSON.stringify(parsed, null, 2));\n  process.exit(0);\n} catch (error) {\n  const message = error instanceof SyntaxError ? error.message : \"Unknown error\";\n  console.error(`Invalid JSON: ${message}`);\n  process.exit(1);\n}\n"
