        "content": "import { describe, expect, test } from \"bun:test\";\nimport { resolve } from \"path\";\n\nconst scriptPath = resolve(import.meta.dir, \"validate-json.ts\");\n\nasync function runValidator(input: string) {\n  const proc = Bun.spawn([\"bun\", \"run\", scriptPath], {\n    stdin: new Blob([input]),\n    stdout: \"pipe\",\n    stderr: \"pipe\",\n  });\n  const [exitCode, stdout, stderr] = await Promise.all([\n    proc.exited,\n    new Response(proc.stdout).text(),\n    new Response(proc.stderr).text(),\n  ]);\n  return { exitCode, stdout, stderr };\n}\n\ndescribe(\"validate-json\", () => {\n  test(\"exits 0 and prints parsed output for valid JSON object\", async () => {\n    const { exitCode, stdout } = await runValidator('{\"name\": \"test\"}');\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(\"Valid JSON\");\n    expect(stdout).toContain('\"name\": \"test\"');\n  });\n\n  test(\"exits 0 for valid JSON array\", async () => {\n    const { exitCode, stdout } = await runValidator(\"[1, 2, 3]\");\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(\"Valid JSON\");\n  });\n\n  test(\"exits 1 with error message for invalid JSON\", async () => {\n    const { exitCode, stderr } = await runValidator(\"{not valid json}\");\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"Invalid JSON\");\n  });\n\n  test(\"exits 1 with error message for empty input\", async () => {\n    const { exitCode, stderr } = await runValidator(\"\");\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"No input provided\");\n  });\n});\n"
