import { describe, expect, test } from "bun:test";
import { greet, add, personalGreeting } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  test("personalGreeting returns custom greeting", () => {
    expect(personalGreeting("Alice", "Welcome")).toBe("Welcome, Alice!");
  });

  test("personalGreeting handles empty name", () => {
    expect(personalGreeting("", "Hi")).toBe("Hi, !");
  });

  test("personalGreeting handles empty greeting", () => {
    expect(personalGreeting("Alice", "")).toBe(", Alice!");
  });
});

