        "content": "import { describe, expect, test } from \"bun:test\";\nimport {\n  validateJson,\n  validateAgainstSchema,\n  type JsonSchema,\n} from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  describe(\"valid JSON\", () => {\n    const validCases: [string, string][] = [\n      [\"empty object\", \"{}\"],\n      [\"empty array\", \"[]\"],\n      [\"simple string\", '\"hello\"'],\n      [\"number integer\", \"42\"],\n      [\"number negative\", \"-7\"],\n      [\"number decimal\", \"3.14\"],\n      [\"number exponent\", \"1e10\"],\n      [\"number negative exponent\", \"2.5E-3\"],\n      [\"boolean true\", \"true\"],\n      [\"boolean false\", \"false\"],\n      [\"null\", \"null\"],\n      [\"object with properties\", '{\"name\":\"Alice\",\"age\":30}'],\n      [\"array of mixed types\", '[1,\"two\",true,null]'],\n      [\"nested object\", '{\"a\":{\"b\":{\"c\":1}}}'],\n      [\"nested array\", \"[[[1,2],[3,4]],[[5,6]]]\"],\n      [\"string with escapes\", '\"hello\\\\nworld\\\\t\\\\\\\\\"'],\n      [\"string with unicode escape\", '\"\\\\u0041\\\\u0042\"'],\n      [\"string with solidus escape\", '\"path\\\\/to\\\\/file\"'],\n      [\"whitespace around values\", '  { \"key\" : \"value\" }  '],\n      [\"zero\", \"0\"],\n      [\"negative zero\", \"-0\"],\n    ];\n\n    for (const [label, input] of validCases) {\n      test(label, () => {\n        const result = validateJson(input);\n        expect(result.valid).toBe(true);\n        expect(result.error).toBeUndefined();\n      });\n    }\n  });\n\n  describe(\"malformed JSON\", () => {\n    test(\"trailing comma in object\", () => {\n      const result = validateJson('{\"a\":1,}');\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Trailing comma\");\n    });\n\n    test(\"trailing comma in array\", () => {\n      const result = validateJson(\"[1,2,]\");\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Trailing comma\");\n    });\n\n    test(\"unquoted key\", () => {\n      const result = validateJson(\"{key: 1}\");\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Expected property name\");\n    });\n\n    test(\"single quotes\", () => {\n      const result = validateJson(\"{'key': 1}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unclosed object\", () => {\n      const result = validateJson('{\"a\":1');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unclosed array\", () => {\n      const result = validateJson(\"[1,2\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unclosed string\", () => {\n      const result = validateJson('\"hello');\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Unterminated string\");\n    });\n\n    test(\"empty input\", () => {\n      const result = validateJson(\"\");\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Unexpected end of input\");\n    });\n\n    test(\"leading zeros\", () => {\n      const result = validateJson(\"01\");\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Leading zeros\");\n    });\n\n    test(\"extra content after value\", () => {\n      const result = validateJson(\"{}[]\");\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Unexpected content\");\n    });\n\n    test(\"invalid escape in string\", () => {\n      const result = validateJson('\"\\\\x41\"');\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Invalid escape\");\n    });\n\n    test(\"missing colon in object\", () => {\n      const result = validateJson('{\"a\" 1}');\n      expect(result.valid).toBe(false);\n      expect(result.error!.message).toContain(\"Expected ':'\");\n    });\n\n    test(\"lone minus sign\", () => {\n      const result = validateJson(\"-\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"decimal point without following digit\", () => {\n      const result = validateJson(\"1.\");\n      expect(result.valid).toBe(false);\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"empty object\", () => {\n      const result = validateJson(\"{}\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"empty array\", () => {\n      const result = validateJson(\"[]\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"unicode characters in string\", () => {\n      const result = validateJson(JSON.stringify(\"Hello \\u00e9\\u00e8\\u00ea \\u4e16\\u754c\"));\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"deeply nested structure\", () => {\n      let json = \"0\";\n      for (let i = 0; i < 100; i++) {\n        json = `[${json}]`;\n      }\n      const result = validateJson(json);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"deeply nested objects\", () => {\n      let json = '\"leaf\"';\n      for (let i = 0; i < 100; i++) {\n        json = `{\"k\":${json}}`;\n      }\n      const result = validateJson(json);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"error position tracking\", () => {\n      const result = validateJson('{\\n  \"a\": 1,\\n  \"b\": }');\n      expect(result.valid).toBe(false);\n      expect(result.error!.line).toBe(3);\n    });\n\n    test(\"string with all valid escape types\", () => {\n      const result = validateJson('\"\\\\\"\\\\\\\\\\\\/\\\\b\\\\f\\\\n\\\\r\\\\t\\\\u0041\"');\n      expect(result.valid).toBe(true);\n    });\n  });\n});\n\ndescribe(\"validateAgainstSchema\", () => {\n  test(\"validates string type\", () => {\n    const schema: JsonSchema = { type: \"string\" };\n    expect(validateAgainstSchema(\"hello\", schema).valid).toBe(true);\n    expect(validateAgainstSchema(42, schema).valid).toBe(false);\n  });\n\n  test(\"validates number type\", () => {\n    const schema: JsonSchema = { type: \"number\" };\n    expect(validateAgainstSchema(42, schema).valid).toBe(true);\n    expect(validateAgainstSchema(\"42\", schema).valid).toBe(false);\n  });\n\n  test(\"validates boolean type\", () => {\n    const schema: JsonSchema = { type: \"boolean\" };\n    expect(validateAgainstSchema(true, schema).valid).toBe(true);\n    expect(validateAgainstSchema(0, schema).valid).toBe(false);\n  });\n\n  test(\"validates null type\", () => {\n    const schema: JsonSchema = { type: \"null\" };\n    expect(validateAgainstSchema(null, schema).valid).toBe(true);\n    expect(validateAgainstSchema(undefined, schema).valid).toBe(false);\n  });\n\n  test(\"validates object with required properties\", () => {\n    const schema: JsonSchema = {\n      type: \"object\",\n      required: [\"name\", \"age\"],\n      properties: {\n        name: { type: \"string\" },\n        age: { type: \"number\" },\n      },\n    };\n\n    const valid = validateAgainstSchema({ name: \"Alice\", age: 30 }, schema);\n    expect(valid.valid).toBe(true);\n    expect(valid.errors).toHaveLength(0);\n\n    const missingAge = validateAgainstSchema({ name: \"Alice\" }, schema);\n    expect(missingAge.valid).toBe(false);\n    expect(missingAge.errors.some((e) => e.message.includes(\"'age'\"))).toBe(true);\n  });\n\n  test(\"validates nested object properties\", () => {\n    const schema: JsonSchema = {\n      type: \"object\",\n      properties: {\n        address: {\n          type: \"object\",\n          required: [\"city\"],\n          properties: {\n            city: { type: \"string\" },\n          },\n        },\n      },\n    };\n\n    const valid = validateAgainstSchema({ address: { city: \"NYC\" } }, schema);\n    expect(valid.valid).toBe(true);\n\n    const wrongType = validateAgainstSchema({ address: { city: 123 } }, schema);\n    expect(wrongType.valid).toBe(false);\n    expect(wrongType.errors[0].path).toBe(\"$.address.city\");\n  });\n\n  test(\"validates array with items schema\", () => {\n    const schema: JsonSchema = {\n      type: \"array\",\n      items: { type: \"number\" },\n    };\n\n    expect(validateAgainstSchema([1, 2, 3], schema).valid).toBe(true);\n\n    const mixed = validateAgainstSchema([1, \"two\", 3], schema);\n    expect(mixed.valid).toBe(false);\n    expect(mixed.errors[0].path).toBe(\"$[1]\");\n  });\n\n  test(\"reports multiple errors\", () => {\n    const schema: JsonSchema = {\n      type: \"object\",\n      required: [\"a\", \"b\", \"c\"],\n    };\n\n    const result = validateAgainstSchema({}, schema);\n    expect(result.valid).toBe(false);\n    expect(result.errors).toHaveLength(3);\n  });\n\n  test(\"type mismatch at root returns early\", () => {\n    const schema: JsonSchema = {\n      type: \"object\",\n      required: [\"a\"],\n    };\n\n    const result = validateAgainstSchema(\"not an object\", schema);\n    expect(result.valid).toBe(false);\n    expect(result.errors).toHaveLength(1);\n    expect(result.errors[0].path).toBe(\"$\");\n  });\n});\n\ndescribe(\"performance\", () => {\n  test(\"validates large JSON payload in sub-millisecond time\", () => {\n    const items: string[] = [];\n    for (let i = 0; i < 200; i++) {\n      items.push(\n        `{\"id\":${i},\"name\":\"item-${i}\",\"value\":${Math.random()},\"active\":${i % 2 === 0},\"tags\":[\"a\",\"b\",\"c\"],\"nested\":{\"x\":${i},\"y\":\"data-${i}\"}}`\n      );\n    }\n    const largeJson = `[${items.join(\",\")}]`;\n\n    expect(largeJson.length).toBeGreaterThan(10000);\n\n    const iterations = 100;\n    const start = performance.now();\n    for (let i = 0; i < iterations; i++) {\n      const result = validateJson(largeJson);\n      expect(result.valid).toBe(true);\n    }\n    const elapsed = performance.now() - start;\n    const avgMs = elapsed / iterations;\n\n    expect(avgMs).toBeLessThan(1);\n  });\n});\n"
