/**
 * High-performance JSON validation module.
 *
 * Provides structural validation via a single-pass character scanner
 * and schema-based validation for parsed objects.
 */

export interface ValidationError {
  message: string;
  position: number;
  line: number;
  column: number;
}

export interface ValidationResult {
  valid: boolean;
  error?: ValidationError;
}

export interface JsonSchema {
  type: "string" | "number" | "boolean" | "null" | "object" | "array";
  required?: string[];
  properties?: Record<string, JsonSchema>;
  items?: JsonSchema;
}

export interface SchemaValidationError {
  path: string;
  message: string;
}

export interface SchemaValidationResult {
  valid: boolean;
  errors: SchemaValidationError[];
}

/**
 * Validate a raw JSON string using a single-pass character scanner.
 * Returns immediately on the first structural error encountered.
 */
export function validateJson(input: string): ValidationResult {
  const len = input.length;
  let pos = 0;
  let line = 1;
  let col = 1;

  function makeError(message: string): ValidationResult {
    return { valid: false, error: { message, position: pos, line, column: col } };
  }

  function advance(): string {
    const ch = input[pos];
    pos++;
    if (ch === "\n") {
      line++;
      col = 1;
    } else {
      col++;
    }
    return ch;
  }

  function peek(): string {
    return input[pos];
  }

  function skipWhitespace(): void {
    while (pos < len) {
      const ch = input[pos];
      if (ch === " " || ch === "\t" || ch === "\n" || ch === "\r") {
        advance();
      } else {
        break;
      }
    }
  }

  function parseValue(): ValidationResult {
    skipWhitespace();
    if (pos >= len) {
      return makeError("Unexpected end of input");
    }

    const ch = peek();

    if (ch === '"') return parseString();
    if (ch === "{") return parseObject();
    if (ch === "[") return parseArray();
    if (ch === "t" || ch === "f") return parseBooleanLiteral();
    if (ch === "n") return parseNullLiteral();
    if (ch === "-" || (ch >= "0" && ch <= "9")) return parseNumber();

    return makeError(`Unexpected character '${ch}'`);
  }

  function parseString(): ValidationResult {
    if (peek() !== '"') {
      return makeError("Expected '\"'");
    }
    advance(); // opening quote

    while (pos < len) {
      const ch = peek();

      if (ch === "\\") {
        advance();
        if (pos >= len) {
          return makeError("Unexpected end of input in string escape");
        }
        const esc = peek();
        if (
          esc === '"' ||
          esc === "\\" ||
          esc === "/" ||
          esc === "b" ||
          esc === "f" ||
          esc === "n" ||
          esc === "r" ||
          esc === "t"
        ) {
          advance();
        } else if (esc === "u") {
          advance();
          for (let i = 0; i < 4; i++) {
            if (pos >= len) {
              return makeError("Unexpected end of input in unicode escape");
            }
            const hex = peek();
            if (
              !(
                (hex >= "0" && hex <= "9") ||
                (hex >= "a" && hex <= "f") ||
                (hex >= "A" && hex <= "F")
              )
            ) {
              return makeError(`Invalid unicode escape character '${hex}'`);
            }
            advance();
          }
        } else {
          return makeError(`Invalid escape character '${esc}'`);
        }
        continue;
      }

      if (ch === '"') {
        advance(); // closing quote
        return { valid: true };
      }

      const code = ch.charCodeAt(0);
      if (code < 0x20) {
        return makeError("Invalid control character in string");
      }

      advance();
    }

    return makeError("Unterminated string");
  }

  function parseNumber(): ValidationResult {
    if (peek() === "-") {
      advance();
      if (pos >= len || peek() < "0" || peek() > "9") {
        return makeError("Expected digit after '-'");
      }
    }

    if (peek() === "0") {
      advance();
      if (pos < len && peek() >= "0" && peek() <= "9") {
        return makeError("Leading zeros are not allowed");
      }
    } else {
      if (pos >= len || peek() < "1" || peek() > "9") {
        return makeError("Expected digit");
      }
      advance();
      while (pos < len && peek() >= "0" && peek() <= "9") {
        advance();
      }
    }

    if (pos < len && peek() === ".") {
      advance();
      if (pos >= len || peek() < "0" || peek() > "9") {
        return makeError("Expected digit after decimal point");
      }
      while (pos < len && peek() >= "0" && peek() <= "9") {
        advance();
      }
    }

    if (pos < len && (peek() === "e" || peek() === "E")) {
      advance();
      if (pos < len && (peek() === "+" || peek() === "-")) {
        advance();
      }
      if (pos >= len || peek() < "0" || peek() > "9") {
        return makeError("Expected digit in exponent");
      }
      while (pos < len && peek() >= "0" && peek() <= "9") {
        advance();
      }
    }

    return { valid: true };
  }

  function parseBooleanLiteral(): ValidationResult {
    if (input.startsWith("true", pos)) {
      pos += 4;
      col += 4;
      return { valid: true };
    }
    if (input.startsWith("false", pos)) {
      pos += 5;
      col += 5;
      return { valid: true };
    }
    return makeError("Invalid literal");
  }

  function parseNullLiteral(): ValidationResult {
    if (input.startsWith("null", pos)) {
      pos += 4;
      col += 4;
      return { valid: true };
    }
    return makeError("Invalid literal, expected 'null'");
  }

  function parseObject(): ValidationResult {
    advance(); // {
    skipWhitespace();

    if (pos >= len) {
      return makeError("Unexpected end of input in object");
    }

    if (peek() === "}") {
      advance();
      return { valid: true };
    }

    while (true) {
      skipWhitespace();
      if (pos >= len) {
        return makeError("Unexpected end of input in object");
      }

      if (peek() !== '"') {
        return makeError("Expected property name (string) in object");
      }

      const keyResult = parseString();
      if (!keyResult.valid) return keyResult;

      skipWhitespace();
      if (pos >= len || peek() !== ":") {
        return makeError("Expected ':' after property name");
      }
      advance(); // :

      const valResult = parseValue();
      if (!valResult.valid) return valResult;

      skipWhitespace();
      if (pos >= len) {
        return makeError("Unexpected end of input in object");
      }

      if (peek() === "}") {
        advance();
        return { valid: true };
      }

      if (peek() !== ",") {
        return makeError("Expected ',' or '}' in object");
      }
      advance(); // ,

      skipWhitespace();
      if (pos < len && peek() === "}") {
        return makeError("Trailing comma in object");
      }
    }
  }

  function parseArray(): ValidationResult {
    advance(); // [
    skipWhitespace();

    if (pos >= len) {
      return makeError("Unexpected end of input in array");
    }

    if (peek() === "]") {
      advance();
      return { valid: true };
    }

    while (true) {
      const valResult = parseValue();
      if (!valResult.valid) return valResult;

      skipWhitespace();
      if (pos >= len) {
        return makeError("Unexpected end of input in array");
      }

      if (peek() === "]") {
        advance();
        return { valid: true };
      }

      if (peek() !== ",") {
        return makeError("Expected ',' or ']' in array");
      }
      advance(); // ,

      skipWhitespace();
      if (pos < len && peek() === "]") {
        return makeError("Trailing comma in array");
      }
    }
  }

  // Main validation entry point
  if (len === 0) {
    return makeError("Unexpected end of input");
  }

  const result = parseValue();
  if (!result.valid) return result;

  skipWhitespace();
  if (pos < len) {
    return makeError("Unexpected content after JSON value");
  }

  return { valid: true };
}

/**
 * Validate a parsed value against a lightweight JSON schema descriptor.
 * Supports type checking, required properties, nested property schemas, and array item schemas.
 */
export function validateAgainstSchema(
  data: unknown,
  schema: JsonSchema,
  path: string = "$"
): SchemaValidationResult {
  const errors: SchemaValidationError[] = [];

  function validate(value: unknown, s: JsonSchema, currentPath: string): void {
    const actualType = getJsonType(value);

    if (actualType !== s.type) {
      errors.push({
        path: currentPath,
        message: `Expected type '${s.type}', got '${actualType}'`,
      });
      return;
    }

    if (s.type === "object" && typeof value === "object" && value !== null) {
      const obj = value as Record<string, unknown>;

      if (s.required) {
        for (const key of s.required) {
          if (!(key in obj)) {
            errors.push({
              path: `${currentPath}.${key}`,
              message: `Missing required property '${key}'`,
            });
          }
        }
      }

      if (s.properties) {
        for (const [key, propSchema] of Object.entries(s.properties)) {
          if (key in obj) {
            validate(obj[key], propSchema, `${currentPath}.${key}`);
          }
        }
      }
    }

    if (s.type === "array" && Array.isArray(value) && s.items) {
      for (let i = 0; i < value.length; i++) {
        validate(value[i], s.items, `${currentPath}[${i}]`);
      }
    }
  }

  function getJsonType(
    value: unknown
  ): "string" | "number" | "boolean" | "null" | "object" | "array" | "undefined" {
    if (value === null) return "null";
    if (Array.isArray(value)) return "array";
    if (typeof value === "string") return "string";
    if (typeof value === "number") return "number";
    if (typeof value === "boolean") return "boolean";
    if (typeof value === "object") return "object";
    return "undefined";
  }

  validate(data, schema, path);

  return {
    valid: errors.length === 0,
    errors,
  };
}

// CLI entry point
if (import.meta.main) {
  const input = process.argv[2];
  if (!input) {
    console.error("Usage: bun run src/validate-json.ts '<json-string>'");
    process.exit(1);
  }
  const result = validateJson(input);
  if (result.valid) {
    console.log("Valid JSON");
  } else {
    console.error(
      `Invalid JSON: ${result.error!.message} at line ${result.error!.line}, column ${result.error!.column} (position ${result.error!.position})`
    );
    process.exit(1);
  }
}

import { describe, expect, test } from "bun:test";
import {
  validateJson,
  validateAgainstSchema,
  type JsonSchema,
} from "./validate-json";

describe("validateJson", () => {
  describe("valid JSON", () => {
    const validCases: [string, string][] = [
      ["empty object", "{}"],
      ["empty array", "[]"],
      ["simple string", '"hello"'],
      ["number integer", "42"],
      ["number negative", "-7"],
      ["number decimal", "3.14"],
      ["number exponent", "1e10"],
      ["number negative exponent", "2.5E-3"],
      ["boolean true", "true"],
      ["boolean false", "false"],
      ["null", "null"],
      ["object with properties", '{"name":"Alice","age":30}'],
      ["array of mixed types", '[1,"two",true,null]'],
      ["nested object", '{"a":{"b":{"c":1}}}'],
      ["nested array", "[[[1,2],[3,4]],[[5,6]]]"],
      ["string with escapes", '"hello\\nworld\\t\\\\"'],
      ["string with unicode escape", '"\\u0041\\u0042"'],
      ["string with solidus escape", '"path\\/to\\/file"'],
      ["whitespace around values", '  { "key" : "value" }  '],
      ["zero", "0"],
      ["negative zero", "-0"],
    ];

    for (const [label, input] of validCases) {
      test(label, () => {
        const result = validateJson(input);
        expect(result.valid).toBe(true);
        expect(result.error).toBeUndefined();
      });
    }
  });

  describe("malformed JSON", () => {
    test("trailing comma in object", () => {
      const result = validateJson('{"a":1,}');
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Trailing comma");
    });

    test("trailing comma in array", () => {
      const result = validateJson("[1,2,]");
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Trailing comma");
    });

    test("unquoted key", () => {
      const result = validateJson("{key: 1}");
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Expected property name");
    });

    test("single quotes", () => {
      const result = validateJson("{'key': 1}");
      expect(result.valid).toBe(false);
    });

    test("unclosed object", () => {
      const result = validateJson('{"a":1');
      expect(result.valid).toBe(false);
    });

    test("unclosed array", () => {
      const result = validateJson("[1,2");
      expect(result.valid).toBe(false);
    });

    test("unclosed string", () => {
      const result = validateJson('"hello');
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Unterminated string");
    });

    test("empty input", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Unexpected end of input");
    });

    test("leading zeros", () => {
      const result = validateJson("01");
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Leading zeros");
    });

    test("extra content after value", () => {
      const result = validateJson("{}[]");
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Unexpected content");
    });

    test("invalid escape in string", () => {
      const result = validateJson('"\\x41"');
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Invalid escape");
    });

    test("missing colon in object", () => {
      const result = validateJson('{"a" 1}');
      expect(result.valid).toBe(false);
      expect(result.error!.message).toContain("Expected ':'");
    });

    test("lone minus sign", () => {
      const result = validateJson("-");
      expect(result.valid).toBe(false);
    });

    test("decimal point without following digit", () => {
      const result = validateJson("1.");
      expect(result.valid).toBe(false);
    });
  });

  describe("edge cases", () => {
    test("empty object", () => {
      const result = validateJson("{}");
      expect(result.valid).toBe(true);
    });

    test("empty array", () => {
      const result = validateJson("[]");
      expect(result.valid).toBe(true);
    });

    test("unicode characters in string", () => {
      const result = validateJson(JSON.stringify("Hello \u00e9\u00e8\u00ea \u4e16\u754c"));
      expect(result.valid).toBe(true);
    });

    test("deeply nested structure", () => {
      let json = "0";
      for (let i = 0; i < 100; i++) {
        json = `[${json}]`;
      }
      const result = validateJson(json);
      expect(result.valid).toBe(true);
    });

    test("deeply nested objects", () => {
      let json = '"leaf"';
      for (let i = 0; i < 100; i++) {
        json = `{"k":${json}}`;
      }
      const result = validateJson(json);
      expect(result.valid).toBe(true);
    });

    test("error position tracking", () => {
      const result = validateJson('{\n  "a": 1,\n  "b": }');
      expect(result.valid).toBe(false);
      expect(result.error!.line).toBe(3);
    });

    test("string with all valid escape types", () => {
      const result = validateJson('"\\"\\\\\\/\\b\\f\\n\\r\\t\\u0041"');
      expect(result.valid).toBe(true);
    });
  });
});

describe("validateAgainstSchema", () => {
  test("validates string type", () => {
    const schema: JsonSchema = { type: "string" };
    expect(validateAgainstSchema("hello", schema).valid).toBe(true);
    expect(validateAgainstSchema(42, schema).valid).toBe(false);
  });

  test("validates number type", () => {
    const schema: JsonSchema = { type: "number" };
    expect(validateAgainstSchema(42, schema).valid).toBe(true);
    expect(validateAgainstSchema("42", schema).valid).toBe(false);
  });

  test("validates boolean type", () => {
    const schema: JsonSchema = { type: "boolean" };
    expect(validateAgainstSchema(true, schema).valid).toBe(true);
    expect(validateAgainstSchema(0, schema).valid).toBe(false);
  });

  test("validates null type", () => {
    const schema: JsonSchema = { type: "null" };
    expect(validateAgainstSchema(null, schema).valid).toBe(true);
    expect(validateAgainstSchema(undefined, schema).valid).toBe(false);
  });

  test("validates object with required properties", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["name", "age"],
      properties: {
        name: { type: "string" },
        age: { type: "number" },
      },
    };

    const valid = validateAgainstSchema({ name: "Alice", age: 30 }, schema);
    expect(valid.valid).toBe(true);
    expect(valid.errors).toHaveLength(0);

    const missingAge = validateAgainstSchema({ name: "Alice" }, schema);
    expect(missingAge.valid).toBe(false);
    expect(missingAge.errors.some((e) => e.message.includes("'age'"))).toBe(true);
  });

  test("validates nested object properties", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        address: {
          type: "object",
          required: ["city"],
          properties: {
            city: { type: "string" },
          },
        },
      },
    };

    const valid = validateAgainstSchema({ address: { city: "NYC" } }, schema);
    expect(valid.valid).toBe(true);

    const wrongType = validateAgainstSchema({ address: { city: 123 } }, schema);
    expect(wrongType.valid).toBe(false);
    expect(wrongType.errors[0].path).toBe("$.address.city");
  });

  test("validates array with items schema", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "number" },
    };

    expect(validateAgainstSchema([1, 2, 3], schema).valid).toBe(true);

    const mixed = validateAgainstSchema([1, "two", 3], schema);
    expect(mixed.valid).toBe(false);
    expect(mixed.errors[0].path).toBe("$[1]");
  });

  test("reports multiple errors", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["a", "b", "c"],
    };

    const result = validateAgainstSchema({}, schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(3);
  });

  test("type mismatch at root returns early", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["a"],
    };

    const result = validateAgainstSchema("not an object", schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0].path).toBe("$");
  });
});

describe("performance", () => {
  test("validates large JSON payload in sub-millisecond time", () => {
    const items: string[] = [];
    for (let i = 0; i < 200; i++) {
      items.push(
        `{"id":${i},"name":"item-${i}","value":${Math.random()},"active":${i % 2 === 0},"tags":["a","b","c"],"nested":{"x":${i},"y":"data-${i}"}}`
      );
    }
    const largeJson = `[${items.join(",")}]`;

    expect(largeJson.length).toBeGreaterThan(10000);

    const iterations = 100;
    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      const result = validateJson(largeJson);
      expect(result.valid).toBe(true);
    }
    const elapsed = performance.now() - start;
    const avgMs = elapsed / iterations;

    expect(avgMs).toBeLessThan(1);
  });
});

